 if(['boolean','bool'].includes(item.type))control=`<select ${attribute}><option value="true" ${value===true?'selected':''}>true · 启用</option><option value="false" ${value===false?'selected':''}>false · 关闭</option></select>`;
 else if(item.options?.length)control=`<select ${attribute}>${item.options.map(option=>`<option value="${escape(option)}" ${value===option?'selected':''}>${escape(option)}</option>`).join('')}</select>`;
