 const draw=()=>{if(!points.length)return;const w=canvas.clientWidth||760,h=300,d=devicePixelRatio||1,c=canvas.getContext('2d');canvas.width=w*d;canvas.height=h*d;c.setTransform(d,0,0,d,0,0);c.fillStyle='#f4f8f1';c.fillRect(0,0,w,h);const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),zs=points.map(p=>p[2]),center=[(Math.min(...xs)+Math.max(...xs))/2,(Math.min(...ys)+Math.max(...ys))/2,(Math.min(...zs)+Math.max(...zs))/2],span=Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys),Math.max(...zs)-Math.min(...zs),1),scale=Math.min(w*.78,h*.72)/span*zoom,cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);const ordered=points.map((p,i)=>{const [x,y,z]=p.map((v,j)=>v-center[j]),a=x*cy-y*sy,b=x*sy+y*cy,t=(depths[i]-(depthRange[0]||0))/((depthRange[1]-depthRange[0])||1);return{x:w/2+a*scale,y:h/2+(b*sp-z*cp)*scale,depth:b*cp+z*sp,t:Math.max(0,Math.min(1,t))};}).sort((a,b)=>a.depth-b.depth);ordered.forEach(p=>{c.fillStyle='hsl('+Math.round(215-205*p.t)+',78%,'+(48-8*p.t)+'%)';c.fillRect(p.x,p.y,2.8,2.8);});c.fillStyle='#526b4e';c.font='12px Microsoft YaHei';c.fillText('颜色：相对腐蚀深度（蓝浅 → 红深）',12,20);c.fillText('拖动旋转 · 滚轮缩放',12,h-10);};
