$$('[data-fit-mode]').forEach(button=>button.addEventListener('click',()=>{const multivariate=button.dataset.fitMode==='multivariate';$('#fitting-content').hidden=multivariate;$('#multivariate-panel').hidden=!multivariate;$$('[data-fit-mode]').forEach(tab=>{const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active));});}));
mountVisualization($('#visualization-root'));
mountProjectLibrary();
mountSurfaceGeneration($('#surface-generation-panel'),{get:request,post,openJob});
mountTaskIO(request);
mountMorphology($('#simulation-panel'),{get:request,post,openJob});
boot();
setTimeout(bindFiniteElement,0);
function refreshIndividualProgress(){
  const job=currentJob;
  if(!job||job.kind!=='simulation')return;
  const progress=job.progress&&typeof job.progress==='object'?job.progress:job;
  const completed=progress.completed_individuals??job.completed_individuals;
  const total=progress.total_individuals??job.total_individuals;
  if(completed==null||total==null)return;
  const stage=progress.stage??job.stage;
  const totalStages=progress.total_stages??job.total_stages;
  const generation=progress.generation??job.generation;
  const maxgen=progress.maxgen??job.maxgen;
  const state=statuses[job.state]||job.state||'计算中';
  const stageText=stage!=null?` · 阶段 ${stage}${totalStages?` / ${totalStages}`:''}`:'';
  const generationText=generation!=null?` · 迭代 ${generation}${maxgen?` / ${maxgen}`:''}`:'';
  $('#progress-text').textContent=`${state}${stageText}${generationText} · 当前个体 ${completed} / ${total}`;
}
setInterval(refreshIndividualProgress,500);
function previewBenchmarkApplication(row,summary) {
 const policy=applicationPolicy(row),root=$('#benchmark-apply-preview');
 if(!policy.allowed){message('#job-message',policy.reason,true);return;}
 const before=clone(workspace.simulation),candidate=clone(before);
 applyMode(candidate,policy.mode);
 if(policy.mode==='fast'){
  candidate.TAICHI_CONFIG.arch=policy.arch;
  candidate.TAICHI_CONFIG.allow_taichi_parallel=policy.workers>1;
  for(const group of ['STAGE_GA_CONFIG','SINGLE_STAGE_GA_CONFIG']){candidate[group] ||= {};candidate[group].parallel_workers=policy.workers;}
 }
 const paths=['mode','TAICHI_CONFIG.use_taichi','TAICHI_CONFIG.arch','TAICHI_CONFIG.allow_taichi_parallel','STAGE_GA_CONFIG.parallel_workers','SINGLE_STAGE_GA_CONFIG.parallel_workers'];
 root.innerHTML=`<div class="notice"><h4>审查采用方案</h4><p>将采用 ${escape(row.label||row.mode)}。网格、F 与种群数量保持当前值。Taichi 不支持严格随机状态恢复。</p><table><thead><tr><th>配置</th><th>当前</th><th>采用后</th></tr></thead><tbody>${paths.map(path=>`<tr><td>${escape(path)}</td><td>${escape(JSON.stringify(getPath(before,path)))}</td><td>${escape(JSON.stringify(getPath(candidate,path)))}</td></tr>`).join('')}</tbody></table><label class="check-field"><input id="benchmark-apply-seed" type="checkbox">使用本次测量种子 ${escape(row.seed??summary.options?.seed)}（默认保留当前种子 ${escape(before.GA_CONFIG?.seed)}）</label><div class="actions"><button id="benchmark-apply-confirm" class="button primary">应用到腐蚀演化</button><button id="benchmark-apply-cancel" class="button secondary">取消</button></div></div>`;
 root.querySelector('#benchmark-apply-cancel').onclick=()=>{root.innerHTML='';};
 root.querySelector('#benchmark-apply-confirm').onclick=()=>{
  for(const path of paths)if(getPath(candidate,path)!==undefined)setPath(workspace.simulation,path,clone(getPath(candidate,path)));
  if(root.querySelector('#benchmark-apply-seed').checked){workspace.simulation.GA_CONFIG.seed=row.seed??summary.options.seed;workspace.seedMode='fixed';}
  applyMode(workspace.simulation,policy.mode);renderSimulation();invalidatePrecheck();root.innerHTML='';activate('simulation-panel');message('#sim-message','已应用审查后的运行方案；请确认目标后提交新的腐蚀演化任务。');
 };
 root.scrollIntoView({behavior:'smooth',block:'nearest'});
}
